  1	//! "apprt" is the "application runtime" package. This abstracts the
  2	//! application runtime and lifecycle management such as creating windows,
  3	//! getting user input (mouse/keyboard), etc.
  4	//!
  5	//! This enables compile-time interfaces to be built to swap out the underlying
  6	//! application runtime. For example: pure macOS Cocoa, GTK+, browser, etc.
  7	//!
  8	//! The goal is to have different implementations share as much of the core
  9	//! logic as possible, and to only reach out to platform-specific implementation
 10	//! code when absolutely necessary.
 11	const build_config = @import("build_config.zig");
 12	
 13	const structs = @import("apprt/structs.zig");
 14	
 15	pub const action = @import("apprt/action.zig");
 16	pub const ipc = @import("apprt/ipc.zig");
 17	pub const gtk = @import("apprt/gtk.zig");
 18	pub const none = @import("apprt/none.zig");
 19	pub const browser = @import("apprt/browser.zig");
 20	pub const embedded = @import("apprt/embedded.zig");
 21	pub const surface = @import("apprt/surface.zig");
 22	
 23	pub const Action = action.Action;
 24	pub const Runtime = @import("apprt/runtime.zig").Runtime;
 25	pub const Target = action.Target;
 26	
 27	pub const ContentScale = structs.ContentScale;
 28	pub const Clipboard = structs.Clipboard;
 29	pub const ClipboardContent = structs.ClipboardContent;
 30	pub const ClipboardReadResult = structs.ClipboardReadResult;
 31	pub const ClipboardRequest = structs.ClipboardRequest;
 32	pub const ClipboardRequestType = structs.ClipboardRequestType;
 33	pub const ColorScheme = structs.ColorScheme;
 34	pub const CursorPos = structs.CursorPos;
 35	pub const IMEPos = structs.IMEPos;
 36	pub const Selection = structs.Selection;
 37	pub const SurfaceSize = structs.SurfaceSize;
 38	
 39	/// The implementation to use for the app runtime. This is comptime chosen
 40	/// so that every build has exactly one application runtime implementation.
 41	/// Note: it is very rare to use Runtime directly; most usage will use
 42	/// Window or something.
 43	pub const runtime = switch (build_config.artifact) {
 44	    .exe => switch (build_config.app_runtime) {
 45	        .none => none,
 46	        .gtk => gtk,
 47	    },
 48	    .lib => embedded,
 49	    .wasm_module => browser,
 50	};
 51	
 52	pub const App = runtime.App;
 53	pub const Surface = runtime.Surface;
 54	
 55	test {
 56	    _ = Runtime;
 57	    _ = runtime;
 58	    _ = action;
 59	    _ = structs;
 60	}
  1	//! App is the primary GUI application for ghostty. This builds the window,
  2	//! sets up the renderer, etc. The primary run loop is started by calling
  3	//! the "run" function.
  4	const App = @This();
  5	
  6	const std = @import("std");
  7	const builtin = @import("builtin");
  8	const assert = @import("quirks.zig").inlineAssert;
  9	const Allocator = std.mem.Allocator;
 10	const apprt = @import("apprt.zig");
 11	const Surface = @import("Surface.zig");
 12	const input = @import("input.zig");
 13	const configpkg = @import("config.zig");
 14	const Config = configpkg.Config;
 15	const BlockingQueue = @import("datastruct/main.zig").BlockingQueue;
 16	const renderer = @import("renderer.zig");
 17	const font = @import("font/main.zig");
 18	const global = @import("global.zig");
 19	
 20	const log = std.log.scoped(.app);
 21	
 22	const SurfaceList = std.ArrayList(*apprt.Surface);
 23	
 24	/// General purpose allocator
 25	alloc: Allocator,
 26	
 27	/// The list of surfaces that are currently active.
 28	surfaces: SurfaceList,
 29	
 30	/// This is true if the app that Ghostty is in is focused. This may
 31	/// mean that no surfaces (terminals) are focused but the app is still
 32	/// focused, i.e. may an about window. On macOS, this concept is known
 33	/// as the "active" app while focused windows are known as the
 34	/// "main" window.
 35	///
 36	/// This is used to determine if keyboard shortcuts that are non-global
 37	/// should be processed. If the app is not focused, then we don't want
 38	/// to process keyboard shortcuts that are not global.
 39	///
 40	/// This defaults to true since we assume that the app is focused when
 41	/// Ghostty is initialized but a well behaved apprt should call
 42	/// focusEvent to set this to the correct value right away.
 43	focused: bool = true,
 44	
 45	/// The last focused surface. This surface may not be valid;
 46	/// you must always call hasSurface to validate it.
 47	focused_surface: ?*Surface = null,
 48	
 49	/// The mailbox that can be used to send this thread messages. Note
 50	/// this is a blocking queue so if it is full you will get errors (or block).
 51	mailbox: Mailbox.Queue,
 52	
 53	/// The set of font GroupCache instances shared by surfaces with the
 54	/// same font configuration.
 55	font_grid_set: font.SharedGridSet,
 56	
 57	/// The app-scoped render device, shared by the renderers of all surfaces.
 58	device: ?*renderer.Device,
 59	
 60	// Used to rate limit desktop notifications. Some platforms (notably macOS) will
 61	// run out of resources if desktop notifications are sent too fast and the OS
 62	// will kill Ghostty.
 63	last_notification_time: ?std.Io.Timestamp = null,
 64	last_notification_digest: u64 = 0,
 65	
 66	/// The conditional state of the configuration. See the equivalent field
 67	/// in the Surface struct for more information. In this case, this applies
 68	/// to the app-level config and as a default for new surfaces.
 69	config_conditional_state: configpkg.ConditionalState,
 70	
 71	/// Set to false once we've created at least one surface. This
 72	/// never goes true again. This can be used by surfaces to determine
 73	/// if they are the first surface.
 74	first: bool = true,
 75	
 76	pub const CreateError = Allocator.Error || font.SharedGridSet.InitError;
 77	
 78	/// Create a new app instance. This returns a stable pointer to the app
 79	/// instance which is required for callbacks.
 80	pub fn create(alloc: Allocator) CreateError!*App {
 81	    var app = try alloc.create(App);
 82	    errdefer alloc.destroy(app);
 83	    try app.init(alloc);
 84	
 85	    // If font discovery supports warmup, then we call it. Some font
 86	    // mechanisms (e.g. CoreText) have a multi-millisecond one-time cost
 87	    // on startup.
 88	    if (comptime @hasDecl(font.Discover, "warmup")) {
 89	        if (std.Thread.spawn(
 90	            .{},
 91	            font.Discover.warmup,
 92	            .{},
 93	        )) |thr| thr.detach() else |err| {
 94	            log.warn("font warmup thread spawn failed err={}", .{err});
 95	        }
 96	    }
 97	
 98	    // Same for the renderer's graphics API (e.g. Metal), which pays
 99	    // one-time framework initialization costs on first use.
100	    if (comptime @hasDecl(renderer.Device, "warmup")) {
101	        if (std.Thread.spawn(
102	            .{},
103	            renderer.Device.warmup,
104	            .{},
105	        )) |thr| thr.detach() else |err| {
106	            log.warn("renderer warmup thread spawn failed err={}", .{err});
107	        }
108	    }
109	
110	    return app;
111	}
112	
113	/// Initialize the main app instance. This creates the main window, sets
114	/// up the renderer state, compiles the shaders, etc. This is the primary
115	/// "startup" logic.
116	///
117	/// After calling this function, well behaved apprts should then call
118	/// `focusEvent` to set the initial focus state of the app.
119	pub fn init(
120	    self: *App,
121	    alloc: Allocator,
122	) CreateError!void {
123	    var font_grid_set = try font.SharedGridSet.init(alloc);
124	    errdefer font_grid_set.deinit();
125	
126	    self.* = .{
127	        .alloc = alloc,
128	        .surfaces = .empty,
129	        .mailbox = .{},
130	        .font_grid_set = font_grid_set,
131	        .device = null,
132	        .config_conditional_state = .{},
133	    };
134	}
135	
136	pub fn deinit(self: *App) void {
137	    // Clean up all our surfaces
138	    for (self.surfaces.items) |surface| surface.deinit();
139	    self.surfaces.deinit(self.alloc);
140	
141	    // Clean up our font group cache
142	    // We should have zero items in the grid set at this point because
143	    // destroy only gets called when the app is shutting down and this
144	    // should gracefully close all surfaces.
145	    assert(self.font_grid_set.count() == 0);
146	    self.font_grid_set.deinit();
147	
148	    // Clean up our render device. This must happen after all surfaces
149	    // are gone since their renderers borrow it.
150	    if (self.device) |dev| dev.deinit(self.alloc);
151	}
152	
153	pub fn destroy(self: *App) void {
154	    // Deinitialize the app
155	    self.deinit();
156	
157	    // Free the app memory
158	    self.alloc.destroy(self);
159	}
160	
161	/// Tick ticks the app loop. This will drain our mailbox and process those
162	/// events. This should be called by the application runtime on every loop
163	/// tick.
164	pub fn tick(self: *App, rt_app: *apprt.App) !void {
165	    // Drain our mailbox
166	    try self.drainMailbox(rt_app);
167	}
168	
169	/// Update the configuration associated with the app. This can only be
170	/// called from the main thread. The caller owns the config memory. The
171	/// memory can be freed immediately when this returns.
172	pub fn updateConfig(self: *App, rt_app: *apprt.App, config: *const Config) !void {
173	    // Go through and update all of the surface configurations.
174	    for (self.surfaces.items) |surface| {
175	        try surface.core().handleMessage(.{ .change_config = config });
176	    }
177	
178	    // Apply our conditional state. If we fail to apply the conditional state
179	    // then we log and attempt to move forward with the old config.
180	    // We only apply this to the app-level config because the surface
181	    // config applies its own conditional state.
182	    var applied_: ?configpkg.Config = config.changeConditionalState(
183	        self.config_conditional_state,
184	    ) catch |err| err: {
185	        log.warn("failed to apply conditional state to config err={}", .{err});
186	        break :err null;
187	    };
188	    defer if (applied_) |*c| c.deinit();
189	    const applied: *const configpkg.Config = if (applied_) |*c| c else config;
190	
191	    // Notify the apprt that the app has changed configuration.
192	    _ = try rt_app.performAction(
193	        .app,
194	        .config_change,
195	        .{ .config = applied },
196	    );
197	}
198	
199	/// Add an initialized surface. This is really only for the runtime
200	/// implementations to call and should NOT be called by general app users.
201	/// The surface must be from the pool.
202	pub fn addSurface(
203	    self: *App,
204	    rt_surface: *apprt.Surface,
205	) Allocator.Error!void {
206	    try self.surfaces.append(self.alloc, rt_surface);
207	
208	    // Since we have non-zero surfaces, we can cancel the quit timer.
209	    // It is up to the apprt if there is a quit timer at all and if it
210	    // should be canceled.
211	    _ = rt_surface.rtApp().performAction(
212	        .app,
213	        .quit_timer,
214	        .stop,
215	    ) catch |err| {
216	        log.warn("error stopping quit timer err={}", .{err});
217	    };
218	}
219	
220	/// Delete the surface from the known surface list. This will NOT call the
221	/// destructor or free the memory.
222	pub fn deleteSurface(self: *App, rt_surface: *apprt.Surface) void {
223	    // If this surface is the focused surface then we need to clear it.
224	    // There was a bug where we relied on hasSurface to return false and
225	    // just let focused surface be but the allocator was reusing addresses
226	    // after free and giving false positives, so we must clear it.
227	    if (self.focused_surface) |focused| {
228	        if (focused == rt_surface.core()) {
229	            self.focused_surface = null;
230	        }
231	    }
232	
233	    var i: usize = 0;
234	    while (i < self.surfaces.items.len) {
235	        if (self.surfaces.items[i] == rt_surface) {
236	            _ = self.surfaces.swapRemove(i);
237	            continue;
238	        }
239	
240	        i += 1;
241	    }
242	
243	    // If we have no surfaces, we can start the quit timer. It is up to the
244	    // apprt to determine if this is necessary.
245	    if (self.surfaces.items.len == 0) _ = rt_surface.rtApp().performAction(
246	        .app,
247	        .quit_timer,
248	        .start,
249	    ) catch |err| {
250	        log.warn("error starting quit timer err={}", .{err});
251	    };
252	}
253	
254	/// The last focused surface. This is only valid while on the main thread
255	/// before tick is called.
256	pub fn focusedSurface(self: *const App) ?*Surface {
257	    const surface = self.focused_surface orelse return null;
258	    if (!self.hasSurface(surface)) return null;
259	    return surface;
260	}
261	
262	/// Returns true if confirmation is needed to quit the app. It is up to
263	/// the apprt to call this.
264	pub fn needsConfirmQuit(self: *const App) bool {
265	    for (self.surfaces.items) |v| {
266	        if (v.core().needsConfirmQuit()) return true;
267	    }
268	
269	    return false;
270	}
271	
272	/// Drain the mailbox.
273	fn drainMailbox(self: *App, rt_app: *apprt.App) !void {
274	    while (self.mailbox.pop(global.io())) |message| {
275	        if (comptime std.log.logEnabled(.debug, .app)) {
276	            switch (message) {
277	                // these tend to be way too verbose for normal debugging
278	                else => log.debug("mailbox message={t}", .{message}),
279	            }
280	        }
281	        switch (message) {
282	            .open_config => |v| try self.performAction(
283	                rt_app,
284	                .{
285	                    .open_config = switch (v) {
286	                        .os_open => .os_open,
287	                        .new_window => .new_window,
288	                    },
289	                },
290	            ),
291	            .new_window => |msg| try self.newWindow(rt_app, msg),
292	            .close => |surface| self.closeSurface(surface),
293	            .surface_message => |msg| try self.surfaceMessage(msg.surface, msg.message),
294	
295	            // If we're quitting, then we set the quit flag and stop
296	            // draining the mailbox immediately. This lets us defer
297	            // mailbox processing to the next tick so that the apprt
298	            // can try to quit as quickly as possible.
299	            .quit => {
300	                log.info("quit message received, short circuiting mailbox drain", .{});
301	                try self.performAction(rt_app, .quit);
302	                return;
303	            },
304	        }
305	    }
306	}
307	
308	pub fn closeSurface(self: *App, surface: *Surface) void {
309	    if (!self.hasSurface(surface)) return;
310	    surface.close();
311	}
312	
313	pub fn focusSurface(self: *App, surface: *Surface) void {
314	    if (!self.hasSurface(surface)) return;
315	    self.focused_surface = surface;
316	}
317	
318	/// Create a new window
319	pub fn newWindow(self: *App, rt_app: *apprt.App, msg: Message.NewWindow) !void {
320	    const target: apprt.Target = target: {
321	        const parent = msg.parent orelse break :target .app;
322	        if (self.hasSurface(parent)) break :target .{ .surface = parent };
323	        break :target .app;
324	    };
325	
326	    _ = try rt_app.performAction(
327	        target,
328	        .new_window,
329	        {},
330	    );
331	}
332	
333	/// Handle an app-level focus event. This should be called whenever
334	/// the focus state of the entire app containing Ghostty changes.
335	/// This is separate from surface focus events. See the `focused`
336	/// field for more information.
337	pub fn focusEvent(self: *App, focused: bool) void {
338	    // Prevent redundant focus events
339	    if (self.focused == focused) return;
340	
341	    log.debug("focus event focused={}", .{focused});
342	    self.focused = focused;
343	}
344	
345	/// Handle a key event at the app-scope. If this key event is used,
346	/// this will return true and the caller shouldn't continue processing
347	/// the event. If the event is not used, this will return false.
348	///
349	/// If the app currently has focus then all key events are processed.
350	/// If the app does not have focus then only global key events are
351	/// processed.
352	pub fn keyEvent(
353	    self: *App,
354	    rt_app: *apprt.App,
355	    event: input.KeyEvent,
356	) bool {
357	    switch (event.action) {
358	        // We don't care about key release events.
359	        .release => return false,
360	
361	        // Continue processing key press events.
362	        .press, .repeat => {},
363	    }
364	
365	    // Get the keybind entry for this event. We don't support key sequences
366	    // so we can look directly in the top-level set.
367	    const entry = rt_app.config.keybind.set.getEvent(event) orelse return false;
368	    const leaf: input.Binding.Set.GenericLeaf = switch (entry.value_ptr.*) {
369	        // Sequences aren't supported. Our configuration parser verifies
370	        // this for global keybinds but we may still get an entry for
371	        // a non-global keybind.
372	        .leader => return false,
373	
374	        // Leaf entries are good
375	        inline .leaf, .leaf_chained => |leaf| leaf.generic(),
376	    };
377	    const actions: []const input.Binding.Action = leaf.actionsSlice();
378	    assert(actions.len > 0);
379	
380	    // If we aren't focused, then we only process global keybinds.
381	    if (!self.focused and !leaf.flags.global) return false;
382	
383	    // Global keybinds are done using performAll so that they
384	    // can target all surfaces too.
385	    if (leaf.flags.global) {
386	        self.performAllChainedAction(rt_app, actions);
387	        return true;
388	    }
389	
390	    // Must be focused to process non-global keybinds
391	    assert(self.focused);
392	    assert(!leaf.flags.global);
393	
394	    // If we are focused, then we process keybinds only if they are
395	    // app-scoped. Otherwise, we do nothing. Surface-scoped should
396	    // be processed by Surface.keyEvent. For chained actions, all
397	    // actions must be app-scoped.
398	    for (actions) |action| if (action.scoped(.app) == null) return false;
399	    for (actions) |action| {
400	        self.performAction(
401	            rt_app,
402	            action.scoped(.app).?,
403	        ) catch |err| {
404	            log.warn("error performing app keybind action action={s} err={}", .{
405	                @tagName(action),
406	                err,
407	            });
408	        };
409	    }
410	
411	    return true;
412	}
413	
414	/// Call to notify Ghostty that the color scheme for the app has changed.
415	/// "Color scheme" in this case refers to system themes such as "light/dark".
416	pub fn colorSchemeEvent(
417	    self: *App,
418	    rt_app: *apprt.App,
419	    scheme: apprt.ColorScheme,
420	) !void {
421	    const new_scheme: configpkg.ConditionalState.Theme = switch (scheme) {
422	        .light => .light,
423	        .dark => .dark,
424	    };
425	
426	    // If our scheme didn't change, then we don't do anything.
427	    if (self.config_conditional_state.theme == new_scheme) return;
428	
429	    // Setup our conditional state which has the current color theme.
430	    self.config_conditional_state.theme = new_scheme;

   430	    self.config_conditional_state.theme = new_scheme;
   431	
   432	    // Request our configuration be reloaded because the new scheme may
   433	    // impact the colors of the app.
   434	    _ = try rt_app.performAction(
   435	        .app,
   436	        .reload_config,
   437	        .{ .soft = true },
   438	    );
   439	}
   440	
   441	/// Perform a binding action. This only accepts actions that are scoped
   442	/// to the app. Callers can use performAllAction to perform any action
   443	/// and any non-app-scoped actions will be performed on all surfaces.
   444	pub fn performAction(
   445	    self: *App,
   446	    rt_app: *apprt.App,
   447	    action: input.Binding.Action.Scoped(.app),
   448	) !void {
   449	    switch (action) {
   450	        .unbind => unreachable,
   451	        .ignore => {},
   452	        .quit => _ = try rt_app.performAction(.app, .quit, {}),
   453	        .new_window => _ = try self.newWindow(rt_app, .{ .parent = null }),
   454	        .open_config => |v| _ = try rt_app.performAction(
   455	            .app,
   456	            .open_config,
   457	            switch (v) {
   458	                .os_open => .os_open,
   459	                .new_window => .new_window,
   460	            },
   461	        ),
   462	        .reload_config => _ = try rt_app.performAction(.app, .reload_config, .{}),
   463	        .set_window_theme => |v| _ = try rt_app.performAction(
   464	            .app,
   465	            .set_window_theme,
   466	            switch (v) {
   467	                .config => .config,
   468	                .system => .system,
   469	                .light => .light,
   470	                .dark => .dark,
   471	            },
   472	        ),
   473	        .close_all_windows => _ = try rt_app.performAction(.app, .close_all_windows, {}),
   474	        .toggle_quick_terminal => _ = try rt_app.performAction(.app, .toggle_quick_terminal, {}),
   475	        .toggle_visibility => _ = try rt_app.performAction(.app, .toggle_visibility, {}),
   476	        .check_for_updates => _ = try rt_app.performAction(.app, .check_for_updates, {}),
   477	        .show_gtk_inspector => _ = try rt_app.performAction(.app, .show_gtk_inspector, {}),
   478	        .undo => _ = try rt_app.performAction(.app, .undo, {}),
   479	
   480	        .redo => _ = try rt_app.performAction(.app, .redo, {}),
   481	    }
   482	}
   483	
   484	/// Performs a chained action. We will continue executing each action
   485	/// even if there is a failure in a prior action.
   486	pub fn performAllChainedAction(
   487	    self: *App,
   488	    rt_app: *apprt.App,
   489	    actions: []const input.Binding.Action,
   490	) void {
   491	    for (actions) |action| {
   492	        self.performAllAction(rt_app, action) catch |err| {
   493	            log.warn("error performing chained action action={s} err={}", .{
   494	                @tagName(action),
   495	                err,
   496	            });
   497	        };
   498	    }
   499	}
   500	
   501	/// Perform an app-wide binding action. If the action is surface-specific
   502	/// then it will be performed on all surfaces. To perform only app-scoped
   503	/// actions, use performAction.
   504	pub fn performAllAction(
   505	    self: *App,
   506	    rt_app: *apprt.App,
   507	    action: input.Binding.Action,
   508	) !void {
   509	    switch (action.scope()) {
   510	        // App-scoped actions are handled by the app so that they aren't
   511	        // repeated for each surface (since each surface forwards
   512	        // app-scoped actions back up).
   513	        .app => try self.performAction(
   514	            rt_app,
   515	            action.scoped(.app).?, // asserted through the scope match
   516	        ),
   517	
   518	        // Surface-scoped actions are performed on all surfaces. Errors
   519	        // are logged but processing continues.
   520	        .surface => for (self.surfaces.items) |surface| {
   521	            _ = surface.core().performBindingAction(action) catch |err| {
   522	                log.warn("error performing binding action on surface id={x} err={}", .{
   523	                    surface.core().id,
   524	                    err,
   525	                });
   526	            };
   527	        },
   528	    }
   529	}
   530	
   531	/// Handle a window message
   532	fn surfaceMessage(self: *App, surface: *Surface, msg: apprt.surface.Message) !void {
   533	    // We want to ensure our window is still active. Window messages
   534	    // are quite rare and we normally don't have many windows so we do
   535	    // a simple linear search here.
   536	    if (self.hasSurface(surface)) {
   537	        try surface.handleMessage(msg);
   538	    }
   539	
   540	    // Window was not found, it probably quit before we handled the message.
   541	    // Not a problem.
   542	}
   543	
   544	fn hasSurface(self: *const App, surface: *const Surface) bool {
   545	    for (self.surfaces.items) |v| {
   546	        if (v.core() == surface) return true;
   547	    }
   548	
   549	    return false;
   550	}
   551	
   552	/// Search for a surface by a 64 bit unique ID.
   553	pub fn findSurfaceByID(self: *const App, id: u64) ?*Surface {
